  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Katedrála v Turku', 'Národní svatyně Finska ze 13. století je nejvýznamnější středověkou stavbou země a dominantou nejstaršího finského města. Před startem okruhu stojí za to projít se po nábřeží řeky Aury, kde kotví historické lodě a žijí kavárny. Motorku pohodlně zaparkujete u katedrály.', 60.4525, 22.2783, 'https://commons.wikimedia.org/wiki/Special:FilePath/Turun%20tuomiokirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Turun%20tuomiokirkko.jpg"}'::text[], 0),
    (v_route, 'Parainen', 'Brána do souostroví a městečko vyrostlé kolem obřího vápencového lomu, jednoho z největších v severní Evropě. Od středověkého kamenného kostela se silnice noří mezi mosty a hráze spojující první ostrovy. Odtud už jedete ostrovní rytmus — klid, moře a žula.', 60.3020, 22.3005, 'https://commons.wikimedia.org/wiki/Special:FilePath/Paraisten%20kirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Paraisten%20kirkko.jpg"}'::text[], 1),
    (v_route, 'Nauvo – přístav', 'Nejživější zastávka okruhu: malebný jachtařský přístav s dřevěnými domky, zmrzlinou a promenádou, v létě plný lodí z celého Baltu. Nad přístavem stojí středověký kamenný kostel svatého Olafa. Ideální místo na první delší pauzu a fotku s motorkou u mola.', 60.1946, 21.9105, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nauvon%20kirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nauvon%20kirkko.jpg"}'::text[], 2),
    (v_route, 'Restaurace: L''Escale (Nauvo)', 'Vyhlášená restaurace přímo v přístavu Nauvo s francouzsko-ostrovní kuchyní, čerstvými rybami a výhledem na kotvící plachetnice. Patří k nejlépe hodnoceným podnikům celého souostroví a v sezóně bývá plno, přijeďte raději mimo poledne. Skvělé místo na oběd v půlce prvního ostrovního úseku.', 60.1950, 21.9120, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nauvon%20kirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nauvon%20kirkko.jpg"}'::text[], 3),
    (v_route, 'Korppoo', 'Ostrov s hlubokými lesy a středověkým kostelem svatého Michala, kde silnice kličkuje mezi skalisky a zálivy. Z Korppoo odplouvá delší trajekt do Houtskari — plavba mezi stovkami ostrůvků je jedním z vrcholů celé trasy. V přístavu Galtby si dejte kávu, než loď připluje.', 60.1610, 21.5680, 'https://commons.wikimedia.org/wiki/Special:FilePath/Korppoon%20kirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Korppoon%20kirkko.jpg"}'::text[], 4),
    (v_route, 'Houtskari', 'Nejodlehlejší obydlený kout okruhu, kde se mluví převážně švédsky a čas plyne pomaleji. Dřevěný kostel, drobné farmy a jednoproudé silničky mezi pastvinami dávají jízdě úplně jiný rozměr. Odtud pokračuje dlouhý trajekt přes Iniö směrem na Kustavi.', 60.2225, 21.3705, 'https://commons.wikimedia.org/wiki/Special:FilePath/Houtskarin%20kirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Houtskarin%20kirkko.jpg"}'::text[], 5),
    (v_route, 'Kustavi', 'Poslední ostrovní obec okruhu, proslulá dřevěným kostelem a v červenci humornými slavnostmi lososa. Zpáteční úsek do Turku po silnici 192 je svižný, s dlouhými plynulými zatáčkami mezi lesy a zálivy. Dobré místo doplnit palivo před závěrečnou stovkou kilometrů.', 60.5462, 21.3583, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kustavin%20kirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kustavin%20kirkko.jpg"}'::text[], 6);
  insert into public.routes
