  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Mariehamn – plachetnice Pommern', 'Hlavní město Åland je město námořníků: v západním přístavu kotví čtyřstěžňová plachetnice Pommern, jediná loď svého druhu na světě dochovaná v původním stavu, dnes muzeum. Lipami lemovaná třída Esplanadi zve na kávu před startem okruhu. Odtud vyrážíte na sever do vnitrozemí souostroví.', 60.0940, 19.9280, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pommern%20Mariehamn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pommern%20Mariehamn.jpg"}'::text[], 0),
    (v_route, 'Hrad Kastelholm', 'Jediný středověký hrad Åland, sídlo švédských správců souostroví ze 14. století, malebně posazený u mořské zátoky v Sundu. Prohlídka nádvoří a věží zabere hodinku, hned vedle je skanzen Jan Karlsgården s větrnými mlýny. Silnice k hradu se vlní mezi poli a patří k nejhezčím úsekům okruhu.', 60.2318, 20.0743, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kastelholms%20slott.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kastelholms%20slott.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Smakbyn (Kastelholm)', 'Gastronomická vesnička slavného ålandského šéfkuchaře Michaela Björklunda hned u hradu Kastelholm. Poctivá severská kuchyně z místních surovin, vlastní palírna a skvělé hodnocení — jedna z nejlepších kuchyní celého souostroví. Ideální oběd v první třetině okruhu.', 60.2300, 20.0700, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kastelholms%20slott.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kastelholms%20slott.jpg"}'::text[], 2),
    (v_route, 'Pevnost Bomarsund', 'Monumentální ruiny ruské pevnosti z 19. století, kterou v Krymské válce dobyla a vyhodila do povětří britsko-francouzská flotila. Rozlehlé hradby nad mořskou úžinou jsou volně přístupné a nabízejí krásné výhledy i kus dramatické historie. Silnice prochází přímo mezi zbytky opevnění.', 60.2122, 20.2373, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bomarsund.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bomarsund.jpg"}'::text[], 3),
    (v_route, 'Geta a Getabergen', 'Nejsevernější obec hlavního ostrova pod žulovými kopci Getabergen, odkud se otevírá nejlepší výhled na Ålandech — červené skály, borovice a nekonečné moře ostrůvků. Na vrchol vede úzká asfaltka ke kavárně s vyhlídkou. Cestou na sever si užijete nejzatáčkovitější kilometry souostroví.', 60.3819, 19.8459, 'https://commons.wikimedia.org/wiki/Special:FilePath/Geta%20kyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Geta%20kyrka.jpg"}'::text[], 4),
    (v_route, 'Eckerö – Pošta a celnice', 'Empírový Poštovní a celní dům v Eckerö od architekta Engela byl kdysi západní výspou ruského impéria — tady končila pošta z Petrohradu a začínala plavba do Švédska. Dnes v něm sídlí galerie a muzeum, kolem jsou písečné pláže. Poslední zastávka před návratem do Mariehamnu.', 60.2200, 19.5460, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ecker%C3%B6%20post-%20och%20tullhus.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ecker%C3%B6%20post-%20och%20tullhus.jpg"}'::text[], 5);
