  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Pevnost Lappeenranta', 'Historická pevnost na návrší nad přístavem Saimay, kterou postupně budovali Švédové i Rusové. Uvnitř hradeb najdete nejstarší pravoslavný kostel Finska, muzea a dílny řemeslníků, dole v přístavu kotví výletní parníky. Skvělé místo na procházku před startem okruhu.', 61.0665, 28.1849, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lappeenrannan%20linnoitus.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lappeenrannan%20linnoitus.jpg"}'::text[], 0),
    (v_route, 'Peřeje Imatrankoski', 'Nejslavnější finské peřeje v korytě řeky Vuoksy, kam jezdila obdivovat divokou vodu i ruská carevna Kateřina II. Řeka je dnes přehrazená a burácivá show se pouští v letních podvečerech za doprovodu hudby — časy si ověřte předem. Kamenné koryto a park kolem stojí za zastávku i mimo představení.', 61.1719, 28.7787, 'https://commons.wikimedia.org/wiki/Special:FilePath/Imatrankoski.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Imatrankoski.jpg"}'::text[], 1),
    (v_route, 'Imatran Valtionhotelli', 'Pohádkový secesní hotel z roku 1903 ve stylu hradu s věžičkami, postavený pro movité návštěvníky peřejí. I když nebudete nocovat, nahlédněte do haly a dejte si kávu na terase — patří k nejfotogeničtějším budovám Finska. Stojí přímo u peřejí Imatrankoski.', 61.1735, 28.7770, 'https://commons.wikimedia.org/wiki/Special:FilePath/Imatran%20valtionhotelli.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Imatran%20valtionhotelli.jpg"}'::text[], 2),
    (v_route, 'Kostel tří křížů (Vuoksenniska)', 'Mistrovské dílo Alvara Aalta z roku 1958 s asymetrickými bílými klenbami a 103 okny, z nichž žádná dvě nejsou stejná. Ikona moderní sakrální architektury, kterou jezdí obdivovat architekti z celého světa. Leží kousek od silnice 62 na severním okraji Imatry.', 61.2065, 28.7870, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kolmen%20ristin%20kirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kolmen%20ristin%20kirkko.jpg"}'::text[], 3),
    (v_route, 'Most Puumalansalmi', 'Elegantní obloukový most klenoucí se vysoko nad úžinou Puumalansalmi, kudy proplouvají lodě mezi jižní a severní Saimaou. Z vyhlídkové plošiny je jeden z nejhezčích jezerních výhledů Finska. Městečko Puumala pod mostem žije v létě přístavem a je přirozenou pauzou v půlce okruhu.', 61.5262, 28.1762, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puumalansalmen%20silta.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Puumalansalmen%20silta.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Sahanlahti (Puumala)', 'Oblíbený letní resort v zátoce staré pily kousek od Puumaly s restaurací zaměřenou na místní ryby ze Saimay a poctivou finskou kuchyni. Hosté chválí polohu přímo u vody i domácí dezerty. Ideální oběd před zpáteční jízdou po západním břehu přes Taipalsaari.', 61.5560, 28.2360, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puumalansalmen%20silta.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Puumalansalmen%20silta.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Olavinlinna', 'Nejzachovalejší středověký hrad severní Evropy z roku 1475 stojí na skalnatém ostrůvku uprostřed jezerní úžiny a je symbolem celého Savonska. V létě hostí světoznámý operní festival, mimo představení se prochází věže a hradby s výhledy na Saimau. K hradu se jde po pontonovém mostě přímo z centra Savonlinny.', 61.8642, 28.9004, 'https://commons.wikimedia.org/wiki/Special:FilePath/Olavinlinna.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Olavinlinna.jpg"}'::text[], 0),
    (v_route, 'Kostel v Kerimäki', 'Největší dřevěný kostel na světě: 45 metrů dlouhý, 27 metrů vysoký a s místem pro více než tři tisíce věřících. Postavili ho v roce 1847 a dodnes se vedou legendy o tom, zda za jeho rozměry nemůže záměna stop a metrů. Interiér z holého dřeva je nezapomenutelný.', 61.9128, 29.2831, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kerim%C3%A4en%20kirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kerim%C3%A4en%20kirkko.jpg"}'::text[], 1),
    (v_route, 'Lusto – muzeum lesa', 'Národní muzeum lesa a lesnictví na kraji hřebene Punkaharju vypráví, proč je les duší Finska — od těžby dřeva po motorové pily a savotské sruby. Moderní expozice zaujme i nelesníky a kavárna je příjemnou pauzou. Odtud už začíná slavná hřebenová silnice.', 61.8047, 29.3179, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lusto.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lusto.jpg"}'::text[], 2),
    (v_route, 'Hřeben Punkaharju', 'Sedmikilometrová písečná šíje z doby ledové mezi jezery Puruvesi a Pihlajavesi, po níž vede historická silnička mezi staletými borovicemi — voda se leskne po obou stranách jen pár metrů od kol. Finové ji volí za svou národní krajinu a chránili ji už carové. Jeďte pomalu a zastavte na některé z vyhlídek.', 61.7623, 29.3777, 'https://commons.wikimedia.org/wiki/Special:FilePath/Punkaharju.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Punkaharju.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Hotelli Punkaharju', 'Nejstarší hotel Finska z roku 1845, bývalý carský lesnický dům přímo na hřebeni, dnes stylový podnik se špičkovou kuchyní z lokálních surovin — ryby z Puruvesi, houby a lesní plody. Terasa s výhledem na jezero je ideální na oběd. V sezóně doporučujeme rezervaci.', 61.7729, 29.3450, 'https://commons.wikimedia.org/wiki/Special:FilePath/Punkaharjun%20valtionhotelli.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Punkaharjun%20valtionhotelli.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Vyhlídka Ukko-Koli', 'Nejikoničtější výhled Finska: z bílých křemencových skal Ukko-Koli se otevírá panorama jezera Pielinen s ostrůvky až k obzoru, které maloval Gallen-Kallela a skládal podle něj Sibelius. Od horního parkoviště u hotelu je to na vrchol deset minut pěšky po chodníku. Ranní světlo a podzimní barvy jsou nejpůsobivější.', 63.0966, 29.8065, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ukko-Koli.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ukko-Koli.jpg"}'::text[], 0),
    (v_route, 'Juuka', 'Karelské městečko proslulé těžbou mastku a starou dřevěnou čtvrtí Puu-Juuka kolem kostela, kde řemeslníci dodnes drží tradiční živnosti. Příjemná krátká zastávka na kávu v půlce západního břehu. Odtud pokračuje silnice 6 svižně na sever do Nurmesu.', 63.2420, 29.2520, 'https://commons.wikimedia.org/wiki/Special:FilePath/Juuan%20kirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Juuan%20kirkko.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Bomban talo (Nurmes)', 'Mohutný vyřezávaný karelský dům postavený podle statku z ruské Karélie, dnes vyhlášená restaurace s karelským bufetem — pirohy kalitt, pečené maso z pece a lesní plody. U jezera vedle stojí celá karelská vesnička a lázně. Nejlepší oběd na severní špici okruhu.', 63.5410, 29.1793, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bomban%20talo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bomban%20talo.jpg"}'::text[], 2),
    (v_route, 'Lieksa – Pielisen museo', 'Druhý největší skanzen Finska s takřka stovkou dřevěných staveb od kuřných chalup po savotské sruby dřevorubců vypráví o drsném životě na východní hranici. Leží u řeky přímo v Liekse na východním břehu Pielinen. Dobrá protahovací pauza na zpáteční cestě.', 63.3130, 30.0430, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pielisen%20museo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pielisen%20museo.jpg"}'::text[], 3),
    (v_route, 'Paateri – ateliér Evy Ryynänen', 'Lesní ateliér a dřevěný kostelík sochařky Evy Ryynänen ve Vuonislahti, celý vyřezaný z borového dřeva včetně oltáře z kořenů. Místo má zvláštní tichou atmosféru a patří k nejpůsobivějším zastávkám Severní Karélie. Ke kostelíku vede krátká odbočka po užší silničce.', 63.1547, 29.9862, 'https://commons.wikimedia.org/wiki/Special:FilePath/Paaterin%20kirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Paaterin%20kirkko.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Häme', 'Červený cihlový hrad ze 13. století na břehu jezera Vanajavesi, jeden ze tří středověkých královských hradů Finska. Švédové z něj spravovali celé vnitrozemí, později sloužil jako vězení. Prohlídka nádvoří a sálů zabere hodinku, kolem hradu je příjemné nábřeží.', 61.0039, 24.4620, 'https://commons.wikimedia.org/wiki/Special:FilePath/H%C3%A4meen%20linna.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/H%C3%A4meen%20linna.jpg"}'::text[], 0),
    (v_route, 'Park a rozhledna Aulanko', 'Anglický krajinářský park z přelomu století s žulovou rozhlednou, odkud se otevírá klasický pohled na lesnaté hřbety a jezero — další z finských národních krajin. Nahoru k věži vede úzká parková asfaltka. Ráno tu bývá liduprázdno a světlo na fotky nejlepší.', 61.0225, 24.4580, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aulangon%20n%C3%A4k%C3%B6torni.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aulangon%20n%C3%A4k%C3%B6torni.jpg"}'::text[], 1),
    (v_route, 'Kostel svatého Kříže v Hattule', 'Nejcennější středověký kostel Finska z cihel, jehož klenby pokrývá přes 180 dochovaných fresek z počátku 16. století — biblický komiks, který věřícím vyprávěl písmo. Otevřeno bývá v létě, mimo sezónu se dívejte aspoň zvenku. Stojí kousek od staré Volské cesty.', 61.0570, 24.3710, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hattulan%20Pyh%C3%A4n%20Ristin%20kirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hattulan%20Pyh%C3%A4n%20Ristin%20kirkko.jpg"}'::text[], 2),
    (v_route, 'Sklárna Iittala', 'Vesnice, kde se od roku 1881 fouká nejslavnější finské sklo — vázy Alvara Aalta i skleničky, které zná celý svět. V hutní hale sledujete skláře při práci, vedle je muzeum a podnikový obchod s outletem. Povinná zastávka pro každého, kdo veze domů dárek.', 61.0740, 24.1210, 'https://commons.wikimedia.org/wiki/Special:FilePath/Iittalan%20lasitehdas.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Iittalan%20lasitehdas.jpg"}'::text[], 3),
    (v_route, 'Visavuori – ateliér Emila Wikströma', 'Ateliér a vila sochaře Emila Wikströma na šíji mezi jezery u Sääksmäki, postavené v národně romantickém stylu s karelskými srubovými prvky. Sochy, sauna u vody a výhledy na Vanajavesi tvoří jedno z nejpůvabnějších uměleckých míst Finska. Cesta k němu vede přes elegantní most Sääksmäen silta.', 61.1836, 24.0446, 'https://commons.wikimedia.org/wiki/Special:FilePath/Visavuori.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Visavuori.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Vanajanlinna', 'Honosný lovecký zámek tabákového magnáta Rosenlewa z 20. let dnes slouží jako hotel s vyhlášenou restaurací — moderní severská kuchyně, zvěřina a vinný sklep patří k nejlepším v kraji. Zámek stojí v golfovém areálu u jezera kousek od Hämeenlinny. Skvělá tečka okruhu.', 60.9760, 24.5760, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vanajanlinna.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vanajanlinna.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Vaasa', 'Slunečné přístavní město obnovené po požáru v empírovém stylu, dnes centrum dvojjazyčného pobřeží. Před startem stojí za to projet nábřežní promenádu a náměstí s kostelem. Odtud vede silnice 724 rovnou na sever k souostroví.', 63.0956, 21.6127, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vaasan%20kirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vaasan%20kirkko.jpg"}'::text[], 0),
    (v_route, 'Replotský most', 'Nejdelší most Finska (1045 m) elegantně překlenuje úžinu na ostrov Raippaluoto a je sám o sobě zážitkem — z vozovky vidíte mělké moře poseté kamennými ostrůvky. U mostu je vyhlídkové parkoviště a infocentrum Kvarkenu. Za silnějšího větru jeďte plynule a počítejte s poryvy.', 63.2295, 21.4400, 'https://commons.wikimedia.org/wiki/Special:FilePath/Raippaluodon%20silta.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Raippaluodon%20silta.jpg"}'::text[], 1),
    (v_route, 'Svedjehamn a Kvarken (UNESCO)', 'Rybářský přístav v Björköby na konci ostrovní silničky, srdce souostroví Kvarken zapsaného na seznam UNESCO — pevnina se tu po době ledové stále zvedá téměř centimetr ročně a moře se mění v louky. Vystoupejte na vyhlídkovou věž Saltkaret nad valy morénových hřbetů. Jedno z nejzvláštnějších pobřeží Evropy.', 63.3560, 21.2210, 'https://commons.wikimedia.org/wiki/Special:FilePath/Svedjehamn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Svedjehamn.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Salteriet (Svedjehamn)', 'Letní restaurace ve staré solírně sleďů přímo na molu ve Svedjehamnu, vyhlášená čerstvými rybami z Kvarkenu a domácími moučníky. Hosté milují polohu i atmosféru rybářské osady. Ideální oběd před návratem na pevninu — v sezóně bývá plno.', 63.3565, 21.2215, 'https://commons.wikimedia.org/wiki/Special:FilePath/Svedjehamn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Svedjehamn.jpg"}'::text[], 3),
    (v_route, 'Nykarleby', 'Půvabné švédskojazyčné městečko na řece s empírovým kostelem a dřevěnými domky, rodiště spisovatele Zachariase Topelia. Stará pobřežní silnice sem přivádí klidným tempem mezi poli a březovými alejemi. Příjemná krátká pauza na kávu.', 63.5225, 22.5305, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nykarleby%20kyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nykarleby%20kyrka.jpg"}'::text[], 4),
    (v_route, 'Jakobstad – čtvrť Skata', 'Historická dřevěná čtvrť s třemi stovkami pestrobarevných domků námořníků a dělníků tabákové továrny, jedna z nejzachovalejších ve Finsku. Úzkými uličkami se projděte pěšky, motorku nechte u přístavu. Město založené na námořním obchodu dodnes staví plachetnice.', 63.6790, 22.7010, 'https://commons.wikimedia.org/wiki/Special:FilePath/Skata,%20Jakobstad.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Skata,%20Jakobstad.jpg"}'::text[], 5),
    (v_route, 'Kokkola – Neristan', 'Cíl trasy v Kokkole korunuje Neristan — Dolní město s mřížkou ulic plných dřevěných kupeckých domů ze 17. a 18. století. V anglickém parku u přístavu je vystavena dělová šalupa ukořistěná Britům v Krymské válce, jediná svého druhu. Kavárny v dřevěných domech jsou ideální tečkou.', 63.8385, 23.1310, 'https://commons.wikimedia.org/wiki/Special:FilePath/Neristan,%20Kokkola.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Neristan,%20Kokkola.jpg"}'::text[], 6);
