  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Rukatunturi', 'Nejznámější lyžařská hora východního Finska se v létě mění v tichý fjell s gondolou na vrchol a výhledy přes nekonečnou tajgu až do Ruska. Horská vesnice pod sjezdovkami žije i mimo zimu — kavárny, vyhlídky a startovní bod slavného treku Karhunkierros. Krátká odbočka ze silnice 5 stojí za to.', 66.1650, 29.1478, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rukatunturi.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rukatunturi.jpg"}'::text[], 0),
    (v_route, 'Restaurace: Riipisen Riistaravintola (Ruka)', 'Legendární zvěřinová restaurace ve vesnici Ruka, kde ochutnáte medvěda, soba i sníh polárky — tedy speciality, které jinde v Evropě nenajdete. Sobí filet s brusinkami je klasika, hodnocení má podnik dlouhodobě vynikající. Ideální vydatný oběd před národním parkem.', 66.1656, 29.1490, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rukatunturi.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rukatunturi.jpg"}'::text[], 1),
    (v_route, 'Vodopád Kiutaköngäs', 'Nejfotografovanější místo parku Oulanka: řeka Oulankajoki se tu valí přes skalní práh mezi tmavě rudými dolomitovými stěnami. Od návštěvnického centra k vodopádu dojdete pohodlně za deset minut po rovné cestě. Hukot vody a barvy skal si zapamatujete nadlouho.', 66.3705, 29.3134, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kiutak%C3%B6ng%C3%A4s.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kiutak%C3%B6ng%C3%A4s.jpg"}'::text[], 2),
    (v_route, 'Národní park Oulanka', 'Divoké údolí řeky Oulankajoki s borovými lesy, písečnými břehy a visutými mosty patří k nejcennějším kouskům finské přírody a navazuje na ruský park Paanajärvi. Návštěvnické centrum u Kiutaköngäs nabízí expozici a kávu. Vede tudy i osmdesátikilometrový trek Karhunkierros — Medvědí stezka.', 66.3690, 29.3100, 'https://commons.wikimedia.org/wiki/Special:FilePath/Oulanka%20National%20Park.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Oulanka%20National%20Park.jpg"}'::text[], 3),
    (v_route, 'Juuma a Myllykoski', 'Osada Juuma je bránou k Malému medvědímu okruhu (Pieni Karhunkierros): po pár stech metrech pěšky stojíte u starého mlýna na peřejích Myllykoski, jednoho z nejromantičtějších míst parku. Visuté mosty nad divokou vodou jsou zážitek i pro neturisty. K Juumě vede pěkná zvlněná silnička ze silnice 950.', 66.2565, 29.3222, 'https://commons.wikimedia.org/wiki/Special:FilePath/Myllykoski%20Juuma.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Myllykoski%20Juuma.jpg"}'::text[], 4);
