  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Kemi', 'Přístavní město u Botnického zálivu, známé zimním sněhovým hradem a mohutným novogotickým kostelem, který dominuje panoramatu. V létě odtud vyplouvá ledoborec Sampo na vyhlídkové plavby. Praktický start okruhu s dobrým zázemím.', 65.7365, 24.5610, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kemin%20kirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kemin%20kirkko.jpg"}'::text[], 0),
    (v_route, 'Dřevěný kostel v Torniu', 'Nejkrásnější dřevěný kostel finského severu z roku 1686 se šindelovou střechou a zvonicí přežil všechny války, které se přes hraniční město přehnaly. Tornio srostlé se švédskou Haparandou je kuriozita sama o sobě — hranici tu přecházíte uprostřed města. Zastavte i u pravoslavného kostelíku z dob cara.', 65.8455, 24.1520, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tornion%20kirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tornion%20kirkko.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Umpitunneli (Tornio)', 'Pivovarská restaurace v centru Tornia navazující na zdejší pivní tradici — vaří se tu poctivá severská jídla k vlastnímu pivu a hodnocení patří k nejlepším ve městě. Sobí speciality a burgery jsou sázka na jistotu. Dobrý oběd před cestou na sever podél řeky.', 65.8470, 24.1440, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tornion%20kirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tornion%20kirkko.jpg"}'::text[], 2),
    (v_route, 'Peřeje Kukkolankoski', 'Nejdelší volně tekoucí peřeje Finska, kde se už od středověku loví síhové do podběráků z dřevěných lávek nad divokou vodou. V létě tu rybáři úlovek rovnou grilují na otevřeném ohni — čerstvě uzený síh je místní pochoutka, kterou nikde jinde nedostanete. Peřeje jsou hned u silnice 21.', 65.9760, 24.0620, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kukkolankoski.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kukkolankoski.jpg"}'::text[], 3),
    (v_route, 'Hora Aavasaksa', 'Legendární vyhlídková hora přímo na polárním kruhu, kam se od 19. století jezdí za půlnočním sluncem — kolem svatojánské noci tu slunce nezapadá vůbec. Na vrchol vede asfaltka, nahoře stojí císařský lovecký pavilon a výhled na údolí řeky do Švédska je fantastický. Patří k měřicím bodům Struveho oblouku (UNESCO).', 66.3833, 23.7333, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aavasaksa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aavasaksa.jpg"}'::text[], 4),
    (v_route, 'Haparanda', 'Švédské hraniční město srostlé s finským Torniem, kdysi jediná legální brána mezi Ruskem a Západem — za první světové války tudy proudili diplomaté, špioni i Lenin. Mohutný měděný kostel a nádraží s dvojím rozchodem kolejí připomínají zvláštní historii. Odtud je to po E4 zpět do Kemi chvilka.', 65.8355, 24.1080, 'https://commons.wikimedia.org/wiki/Special:FilePath/Haparanda%20kyrka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Haparanda%20kyrka.jpg"}'::text[], 5);
