  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Lahti – přístav a Sibeliova hala', 'Přístav v Lahti s dřevěnou koncertní halou Sibeliustalo, jednou z největších dřevostaveb Finska, je příjemným startem okruhu. Nad městem se tyčí trojice skokanských můstků — symbol města zimních sportů. Promenáda u jezera Vesijärvi zve na ranní kávu.', 60.9772, 25.6547, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sibeliustalo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sibeliustalo.jpg"}'::text[], 0),
    (v_route, 'Kanál Vääksy', 'Nejrušnější plavební kanál Finska spojuje jezera Vesijärvi a Päijänne uprostřed městečka Asikkala. V létě je radost sledovat, jak komorou proplouvají desítky lodí denně, kolem jsou kavárny, mlýn a muzeum. Klasická motorkářská zastávka na půl cesty k hřebenovce.', 61.1770, 25.5520, 'https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%A4%C3%A4ksyn%20kanava.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%A4%C3%A4ksyn%20kanava.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Kanavan Panimo (Vääksy)', 'Malý řemeslný pivovar s restaurací ve starých mlýnských budovách přímo u kanálu Vääksy. Vaří tu oceňovaná piva a k nim poctivé jídlo, terasa nad vodou má skvělou atmosféru i hodnocení. Pro řidiče mají nealko speciály — ochutnávku piv si nechte na večer.', 61.1780, 25.5540, 'https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%A4%C3%A4ksyn%20kanava.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%A4%C3%A4ksyn%20kanava.jpg"}'::text[], 2),
    (v_route, 'Pulkkilanharju', 'Osm kilometrů dlouhá šíje z doby ledové, po níž silnice 314 doslova tančí přes jezero Päijänne — voda z obou stran, borovice, mostky mezi ostrůvky a vyhlídka na každém kroku. Jeden z nejhezčích silničních úseků jižního Finska a ráj fotografů. Zastavte na odpočívadle uprostřed hřebene.', 61.2790, 25.5220, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulkkilanharju.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pulkkilanharju.jpg"}'::text[], 3),
    (v_route, 'Sysmä', 'Klidné městečko na severovýchodním břehu Päijänne se středověkým kamenným kostelem svatého Olafa z 15. století. V létě žije letními slavnostmi a knižním festivalem, u přístavu je pláž a kavárny. Nejsevernější bod okruhu — odtud se stáčíte po mostech přes úžiny na západní břeh.', 61.5030, 25.6840, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sysm%C3%A4n%20kirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sysm%C3%A4n%20kirkko.jpg"}'::text[], 4),
    (v_route, 'Padasjoki', 'Obec na západním břehu Päijänne s přístavem, odkud vyplouvají lodě k ostrovům národního parku Päijänne včetně proslulé písečné kosy ostrova Kelvenne. Silnice 24 zpět do Lahti se vlní lesy podél jezera a nabízí poslední porci zatáček. Dobrá zastávka na zmrzlinu u přístavu.', 61.3500, 25.2790, 'https://commons.wikimedia.org/wiki/Special:FilePath/Padasjoen%20kirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Padasjoen%20kirkko.jpg"}'::text[], 5);
