-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — FINSKO (10 tras)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Saariston rengastie – okruh Turkuským souostrovím
  delete from public.routes where name = 'Saariston rengastie – okruh Turkuským souostrovím' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Saariston rengastie – okruh Turkuským souostrovím', 'Legendární Okružní cesta souostrovím je nejslavnější finská letní vyjížďka: z Turku vede po klidných, dokonale asfaltovaných silničkách přes ostrovy Parainen, Nauvo, Korppoo a Houtskari a zpět přes Kustavi. Mezi ostrovy vás přepraví žluté silniční trajekty, které jsou z velké části zdarma a jsou zážitkem samy o sobě. Jede se mezi žulovými skalisky, rudými dřevěnicemi a zátokami Baltu, provoz je minimální a tempo pohodové. Trasa je sjízdná od poloviny června do srpna, kdy jezdí všechny trajektové linky — mimo sezónu okruh nejde uzavřít. Počítejte s celodenním výletem a časem na čekání na trajekty; pozor na hladké žulové nájezdy na přívozy za mokra.', 'loop', 250, 480, 'medium',
     '[{"lat": 60.4518, "lng": 22.2666, "label": "Start: Turku"}, {"lat": 60.3103, "lng": 22.3023, "label": "Parainen"}, {"lat": 60.1946, "lng": 21.9105, "label": "Nauvo"}, {"lat": 60.1610, "lng": 21.5680, "label": "Korppoo"}, {"lat": 60.2225, "lng": 21.3705, "label": "Houtskari"}, {"lat": 60.5462, "lng": 21.3583, "label": "Kustavi"}, {"lat": 60.4518, "lng": 22.2666, "label": "Cíl: Turku"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=60.4518,22.2666&destination=60.4518,22.2666&travelmode=driving&waypoints=60.3103,22.3023%7C60.1946,21.9105%7C60.1610,21.5680%7C60.2225,21.3705%7C60.5462,21.3583', 'https://commons.wikimedia.org/wiki/Special:FilePath/Turun%20tuomiokirkko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Turun%20tuomiokirkko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Paraisten%20kirkko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nauvon%20kirkko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nauvon%20kirkko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Korppoon%20kirkko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Houtskarin%20kirkko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kustavin%20kirkko.jpg"}'::text[], '{"Katedrála v Turku","Parainen","Nauvo – přístav","Restaurace: L''Escale (Nauvo)","Korppoo","Houtskari","Kustavi"}'::text[], '{"FI"}'::text[], false, 3710, 'approved');

  -- Åland – Kastelholm, Bomarsund a Geta
  delete from public.routes where name = 'Åland – Kastelholm, Bomarsund a Geta' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Åland – Kastelholm, Bomarsund a Geta', 'Ostrovní okruh po autonomních Ålandách, švédsky mluvícím souostroví mezi Finskem a Švédskem, kam se s motorkou dostanete trajektem z Turku nebo Helsinek. Silnice jsou úzké, perfektně udržované a téměř prázdné, vedou mezi rudými skalami, poli a stovkami zátok. Okruh z Mariehamnu spojuje středověký hrad Kastelholm, ruiny ruské pevnosti Bomarsund a žulové kopce Getabergen na severu. Nejlepší je červen až srpen, kdy je otevřeno vše včetně vyhlídkových kaváren. Pozor na srnky a jeleny na silnici za šera a na pomalé tempo místní dopravy — na Ålandech nikdo nespěchá.', 'loop', 150, 240, 'easy',
     '[{"lat": 60.0971, "lng": 19.9348, "label": "Start: Mariehamn"}, {"lat": 60.2318, "lng": 20.0743, "label": "Kastelholm"}, {"lat": 60.2122, "lng": 20.2373, "label": "Bomarsund"}, {"lat": 60.3819, "lng": 19.8459, "label": "Geta"}, {"lat": 60.2242, "lng": 19.5479, "label": "Eckerö"}, {"lat": 60.0971, "lng": 19.9348, "label": "Cíl: Mariehamn"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=60.0971,19.9348&destination=60.0971,19.9348&travelmode=driving&waypoints=60.2318,20.0743%7C60.2122,20.2373%7C60.3819,19.8459%7C60.2242,19.5479', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pommern%20Mariehamn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pommern%20Mariehamn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kastelholms%20slott.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kastelholms%20slott.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bomarsund.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Geta%20kyrka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ecker%C3%B6%20post-%20och%20tullhus.jpg"}'::text[], '{"Mariehamn – plachetnice Pommern","Hrad Kastelholm","Restaurace: Smakbyn (Kastelholm)","Pevnost Bomarsund","Geta a Getabergen","Eckerö – Pošta a celnice"}'::text[], '{"FI"}'::text[], false, 3720, 'approved');

  -- Saimaa – Lappeenranta, Imatra a Puumala
  delete from public.routes where name = 'Saimaa – Lappeenranta, Imatra a Puumala' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Saimaa – Lappeenranta, Imatra a Puumala', 'Okruh kolem jižního břehu Saimay, největšího finského jezera, spojuje pevnostní město Lappeenranta, slavné peřeje v Imatře a jednu z nejkrásnějších jezerních silnic země přes Puumalu. Silnice 62 mezi Imatrou a Puumalou se vlní po úzkých šíjích mezi jezerními zálivy — plynulé zatáčky, výhledy na vodu z obou stran a minimum provozu. Cestou potkáte architekturu od secese po Alvara Aalta i ruskou vojenskou historii. Nejlepší období je červen až září; v červenci počítejte s chatařským provozem. Pozor na losy, zvlášť za soumraku, a na občasné remízky s hrubším asfaltem.', 'loop', 240, 330, 'easy',
     '[{"lat": 61.0587, "lng": 28.1887, "label": "Start: Lappeenranta"}, {"lat": 61.1719, "lng": 28.7724, "label": "Imatra"}, {"lat": 61.5262, "lng": 28.1762, "label": "Puumala"}, {"lat": 61.1590, "lng": 28.0570, "label": "Taipalsaari"}, {"lat": 61.0587, "lng": 28.1887, "label": "Cíl: Lappeenranta"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=61.0587,28.1887&destination=61.0587,28.1887&travelmode=driving&waypoints=61.1719,28.7724%7C61.5262,28.1762%7C61.1590,28.0570', 'https://commons.wikimedia.org/wiki/Special:FilePath/Imatrankoski.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lappeenrannan%20linnoitus.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Imatrankoski.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Imatran%20valtionhotelli.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kolmen%20ristin%20kirkko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Puumalansalmen%20silta.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Puumalansalmen%20silta.jpg"}'::text[], '{"Pevnost Lappeenranta","Peřeje Imatrankoski","Imatran Valtionhotelli","Kostel tří křížů (Vuoksenniska)","Most Puumalansalmi","Restaurace: Sahanlahti (Puumala)"}'::text[], '{"FI"}'::text[], false, 3730, 'approved');

  -- Punkaharju a hrad Olavinlinna
  delete from public.routes where name = 'Punkaharju a hrad Olavinlinna' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Punkaharju a hrad Olavinlinna', 'Kompaktní okruh srdcem Jezerního Finska kolem Savonlinny spojuje dva národní poklady: středověký vodní hrad Olavinlinna a hřeben Punkaharju, sedm kilometrů dlouhou písečnou šíji mezi jezery, po níž vede stará silnice považovaná za nejkrásnější kilometry Finska. Cestou navíc největší dřevěný kostel světa v Kerimäki a muzeum lesa Lusto. Silnice jsou klidné, vlnité a s výhledy na vodu prakticky pořád. Nejlépe v červnu až září; v červenci má Savonlinna operní festival na hradě a je plnější. Na hřebeni Punkaharju jeďte pomalu — úzká historická silnice se sdílí s cyklisty a chodci.', 'loop', 180, 240, 'easy',
     '[{"lat": 61.8681, "lng": 28.8862, "label": "Start: Savonlinna"}, {"lat": 61.9128, "lng": 29.2831, "label": "Kerimäki"}, {"lat": 61.8047, "lng": 29.3179, "label": "Lusto"}, {"lat": 61.7576, "lng": 29.3866, "label": "Punkaharju"}, {"lat": 61.7860, "lng": 28.3700, "label": "Sulkava"}, {"lat": 61.8681, "lng": 28.8862, "label": "Cíl: Savonlinna"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=61.8681,28.8862&destination=61.8681,28.8862&travelmode=driving&waypoints=61.9128,29.2831%7C61.8047,29.3179%7C61.7576,29.3866%7C61.7860,28.3700', 'https://commons.wikimedia.org/wiki/Special:FilePath/Olavinlinna.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Olavinlinna.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kerim%C3%A4en%20kirkko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lusto.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Punkaharju.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Punkaharjun%20valtionhotelli.jpg"}'::text[], '{"Hrad Olavinlinna","Kostel v Kerimäki","Lusto – muzeum lesa","Hřeben Punkaharju","Restaurace: Hotelli Punkaharju"}'::text[], '{"FI"}'::text[], false, 3740, 'approved');

  -- Koli a jezero Pielinen
  delete from public.routes where name = 'Koli a jezero Pielinen' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Koli a jezero Pielinen', 'Velký okruh kolem jezera Pielinen v Severní Karélii s vrcholem na Ukko-Koli — nejslavnější vyhlídce Finska, která inspirovala Sibelia i národní malíře. Z Joensuu vede trasa na sever po západním břehu přes vrchy národního parku Koli, dál karelskou krajinou přes Juuku do Nurmesu a zpět po východním břehu přes Lieksu. Silnice 73 a 6 jsou rychlé a plynulé, okresky kolem Koli odmění zatáčkami a stoupáními, na finské poměry vzácnými. Nejlepší je červen až září, na podzim hoří listnaté stráně barvami. Pozor na losy a soby, na severu úseku i na štěrkové vjezdy k vyhlídkám.', 'loop', 330, 420, 'medium',
     '[{"lat": 62.6010, "lng": 29.7636, "label": "Start: Joensuu"}, {"lat": 63.0966, "lng": 29.8065, "label": "Koli"}, {"lat": 63.2420, "lng": 29.2520, "label": "Juuka"}, {"lat": 63.5420, "lng": 29.1390, "label": "Nurmes"}, {"lat": 63.3167, "lng": 30.0264, "label": "Lieksa"}, {"lat": 63.1547, "lng": 29.9862, "label": "Vuonislahti – Paateri"}, {"lat": 62.6010, "lng": 29.7636, "label": "Cíl: Joensuu"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=62.6010,29.7636&destination=62.6010,29.7636&travelmode=driving&waypoints=63.0966,29.8065%7C63.2420,29.2520%7C63.5420,29.1390%7C63.3167,30.0264%7C63.1547,29.9862', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ukko-Koli.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ukko-Koli.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Juuan%20kirkko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bomban%20talo.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pielisen%20museo.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Paaterin%20kirkko.jpg"}'::text[], '{"Vyhlídka Ukko-Koli","Juuka","Restaurace: Bomban talo (Nurmes)","Lieksa – Pielisen museo","Paateri – ateliér Evy Ryynänen"}'::text[], '{"FI"}'::text[], false, 3750, 'approved');

  -- Hrady a ateliéry kraje Häme
  delete from public.routes where name = 'Hrady a ateliéry kraje Häme' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Hrady a ateliéry kraje Häme', 'Pohodový okruh nejstarší kulturní krajinou Finska kolem Hämeenlinny, po stopách středověké Volské cesty (Hämeen Härkätie). Cihlový hrad Häme, středověký kostel v Hattule s unikátními freskami, sklárna Iittala i ateliér sochaře Emila Wikströma na Visavuori — to vše spojují klidné okresky mezi jezery Vanajavesi a poli. Trasa je krátká a nenáročná, ideální na půlden s dlouhými zastávkami. Nejlépe od května do září. Pozor na hustší provoz u Hämeenlinny a na zpomalovací ostrůvky v obcích; jinak jde o čistý relax.', 'loop', 130, 210, 'easy',
     '[{"lat": 60.9959, "lng": 24.4643, "label": "Start: Hämeenlinna"}, {"lat": 61.0570, "lng": 24.3710, "label": "Hattula"}, {"lat": 61.0740, "lng": 24.1210, "label": "Iittala"}, {"lat": 61.1836, "lng": 24.0446, "label": "Visavuori"}, {"lat": 60.9760, "lng": 24.5760, "label": "Vanajanlinna"}, {"lat": 60.9959, "lng": 24.4643, "label": "Cíl: Hämeenlinna"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=60.9959,24.4643&destination=60.9959,24.4643&travelmode=driving&waypoints=61.0570,24.3710%7C61.0740,24.1210%7C61.1836,24.0446%7C60.9760,24.5760', 'https://commons.wikimedia.org/wiki/Special:FilePath/H%C3%A4meen%20linna.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/H%C3%A4meen%20linna.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Aulangon%20n%C3%A4k%C3%B6torni.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hattulan%20Pyh%C3%A4n%20Ristin%20kirkko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Iittalan%20lasitehdas.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Visavuori.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vanajanlinna.jpg"}'::text[], '{"Hrad Häme","Park a rozhledna Aulanko","Kostel svatého Kříže v Hattule","Sklárna Iittala","Visavuori – ateliér Emila Wikströma","Restaurace: Vanajanlinna"}'::text[], '{"FI"}'::text[], false, 3760, 'approved');

  -- Pobřeží Pohjanmaa – Vaasa a Kvarken
  delete from public.routes where name = 'Pobřeží Pohjanmaa – Vaasa a Kvarken' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Pobřeží Pohjanmaa – Vaasa a Kvarken', 'Pobřežní jízda ze severské Vaasy do Kokkoly podél Botnického zálivu, krajem, kde se mluví švédsky a moře pomalu ustupuje zvedající se pevnině. Odbočka přes nejdelší most Finska na souostroví Kvarken (UNESCO) s rybářským přístavem Svedjehamn je vrcholem trasy. Dál se jede po staré pobřežní silnici 749 přes idylické Nykarleby a dřevěné čtvrti Jakobstadu a Kokkoly — rovinaté, plynulé, s vůní moře. Nejlepší je červen až srpen, kdy je souostroví plné světla dlouho do noci. Pozor na boční vítr na mostě a na srnky v pobřežních lesích.', 'poi', 230, 300, 'easy',
     '[{"lat": 63.0951, "lng": 21.6165, "label": "Start: Vaasa"}, {"lat": 63.2295, "lng": 21.4400, "label": "Replotský most"}, {"lat": 63.3560, "lng": 21.2210, "label": "Svedjehamn"}, {"lat": 63.5225, "lng": 22.5305, "label": "Nykarleby"}, {"lat": 63.6746, "lng": 22.7020, "label": "Jakobstad"}, {"lat": 63.8385, "lng": 23.1310, "label": "Cíl: Kokkola"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=63.0951,21.6165&destination=63.8385,23.1310&travelmode=driving&waypoints=63.2295,21.4400%7C63.3560,21.2210%7C63.5225,22.5305%7C63.6746,22.7020', 'https://commons.wikimedia.org/wiki/Special:FilePath/Raippaluodon%20silta.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vaasan%20kirkko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Raippaluodon%20silta.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Svedjehamn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Svedjehamn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nykarleby%20kyrka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Skata,%20Jakobstad.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Neristan,%20Kokkola.jpg"}'::text[], '{"Vaasa","Replotský most","Svedjehamn a Kvarken (UNESCO)","Restaurace: Salteriet (Svedjehamn)","Nykarleby","Jakobstad – čtvrť Skata","Kokkola – Neristan"}'::text[], '{"FI"}'::text[], false, 3770, 'approved');

  -- Kuusamo, Ruka a národní park Oulanka
  delete from public.routes where name = 'Kuusamo, Ruka a národní park Oulanka' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Kuusamo, Ruka a národní park Oulanka', 'Severský okruh na dohled polárnímu kruhu: z Kuusama kolem lyžařské hory Ruka a dál k divokým řekám národního parku Oulanka, kde burácí vodopád Kiutaköngäs mezi rudými skalami. Silnice 5 a okresky ke Käylä a Juumě se vlní mezi kopci, jezery a hlubokou tajgou — na finské poměry nadprůměrně zábavné kilometry. V červnu a červenci se tu skoro nesetmí, na přelomu září bývá ruska — podzimní barvy, kvůli kterým sem Finové jezdí přes celou zemi. Pozor na soby na silnici, jsou tu doslova všude, a na štěrkové dojezdy k parkovištím v národním parku.', 'loop', 180, 270, 'medium',
     '[{"lat": 65.9646, "lng": 29.1886, "label": "Start: Kuusamo"}, {"lat": 66.1650, "lng": 29.1478, "label": "Ruka"}, {"lat": 66.3050, "lng": 29.0700, "label": "Käylä"}, {"lat": 66.3705, "lng": 29.3134, "label": "Kiutaköngäs"}, {"lat": 66.2565, "lng": 29.3222, "label": "Juuma"}, {"lat": 65.9646, "lng": 29.1886, "label": "Cíl: Kuusamo"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=65.9646,29.1886&destination=65.9646,29.1886&travelmode=driving&waypoints=66.1650,29.1478%7C66.3050,29.0700%7C66.3705,29.3134%7C66.2565,29.3222', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rukatunturi.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rukatunturi.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rukatunturi.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kiutak%C3%B6ng%C3%A4s.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Oulanka%20National%20Park.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Myllykoski%20Juuma.jpg"}'::text[], '{"Rukatunturi","Restaurace: Riipisen Riistaravintola (Ruka)","Vodopád Kiutaköngäs","Národní park Oulanka","Juuma a Myllykoski"}'::text[], '{"FI"}'::text[], false, 3780, 'approved');

  -- Údolí řeky Tornio – hranicí dvou zemí
  delete from public.routes where name = 'Údolí řeky Tornio – hranicí dvou zemí' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Údolí řeky Tornio – hranicí dvou zemí', 'Okruh jižním Laponskem podél řeky Tornionjoki, která tvoří nejklidnější hranici světa: nahoru se jede po finském břehu po silnici 21 přes peřeje Kukkolankoski až k hoře Aavasaksa, zpět po švédském břehu po silnici 99 přes Övertorneå do Haparandy. Dvě země, dvě časová pásma a jedna řeka plná lososů — a v červnu půlnoční slunce, kvůli kterému se na Aavasaksu jezdí už od 19. století. Silnice jsou rovné a rychlé, provoz minimální, hraniční mosty se přejíždějí bez zastavení. Nejlepší je červen až srpen. Pozor na soby na finské straně a na měnící se limity po přejezdu do Švédska.', 'loop', 280, 330, 'easy',
     '[{"lat": 65.7360, "lng": 24.5637, "label": "Start: Kemi"}, {"lat": 65.8480, "lng": 24.1466, "label": "Tornio"}, {"lat": 65.9760, "lng": 24.0620, "label": "Kukkolankoski"}, {"lat": 66.3833, "lng": 23.7333, "label": "Aavasaksa"}, {"lat": 66.3880, "lng": 23.6520, "label": "Övertorneå (SE)"}, {"lat": 65.8355, "lng": 24.1180, "label": "Haparanda (SE)"}, {"lat": 65.7360, "lng": 24.5637, "label": "Cíl: Kemi"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=65.7360,24.5637&destination=65.7360,24.5637&travelmode=driving&waypoints=65.8480,24.1466%7C65.9760,24.0620%7C66.3833,23.7333%7C66.3880,23.6520%7C65.8355,24.1180', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kukkolankoski.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kemin%20kirkko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tornion%20kirkko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tornion%20kirkko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kukkolankoski.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Aavasaksa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Haparanda%20kyrka.jpg"}'::text[], '{"Kemi","Dřevěný kostel v Torniu","Restaurace: Umpitunneli (Tornio)","Peřeje Kukkolankoski","Hora Aavasaksa","Haparanda"}'::text[], '{"FI","SE"}'::text[], false, 3790, 'approved');

