  values (v_route, v_branch, 'Päijänne a hřebenovka Pulkkilanharju', 'Okruh kolem jižní části jezera Päijänne, druhého největšího ve Finsku, s vrcholem na hřebeni Pulkkilanharju — úzké šíji z doby ledové, po níž silnice 314 přeskakuje z ostrůvku na ostrůvek mezi hladinami. Z Lahti se jede přes kanál Vääksy s nejrušnější plavební komorou země, dál po hřebeni na sever do Sysmä a zpět po západním břehu přes Padasjoki. Kombinace jezerních výhledů, plynulých zatáček a dřevěných kostelů je ideální jednodenní dávka Jezerního Finska. Nejlépe od května do září. Pozor na cyklisty na hřebenovce a hustší víkendový chatařský provoz kolem Lahti.', 'loop', 230, 300, 'easy',
     '[{"lat": 60.9827, "lng": 25.6612, "label": "Start: Lahti"}, {"lat": 61.1770, "lng": 25.5520, "label": "Vääksy"}, {"lat": 61.2790, "lng": 25.5220, "label": "Pulkkilanharju"}, {"lat": 61.5030, "lng": 25.6840, "label": "Sysmä"}, {"lat": 61.3500, "lng": 25.2790, "label": "Padasjoki"}, {"lat": 60.9827, "lng": 25.6612, "label": "Cíl: Lahti"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=60.9827,25.6612&destination=60.9827,25.6612&travelmode=driving&waypoints=61.1770,25.5520%7C61.2790,25.5220%7C61.5030,25.6840%7C61.3500,25.2790', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pulkkilanharju.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sibeliustalo.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%A4%C3%A4ksyn%20kanava.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%A4%C3%A4ksyn%20kanava.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pulkkilanharju.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sysm%C3%A4n%20kirkko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Padasjoen%20kirkko.jpg"}'::text[], '{"Lahti – přístav a Sibeliova hala","Kanál Vääksy","Restaurace: Kanavan Panimo (Vääksy)","Pulkkilanharju","Sysmä","Padasjoki"}'::text[], '{"FI"}'::text[], false, 3800, 'approved');

